public int maxActivitiesBrute(int[] start, int[] finish) {
    int n = start.length;
    int best = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        List<int[]> chosen = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) chosen.add(new int[]{start[i], finish[i]});
        }
        chosen.sort((a, b) -> Integer.compare(a[0], b[0]));
        boolean ok = true;
        for (int i = 1; i < chosen.size(); i++) {
            if (chosen.get(i)[0] < chosen.get(i - 1)[1]) { ok = false; break; }
        }
        if (ok) best = Math.max(best, chosen.size());
    }
    return best;
}

