def max_activities_brute(self, start: list[int], finish: list[int]) -> int:
    n = len(start)
    best = 0
    for mask in range(1 << n):
        chosen = sorted((start[i], finish[i]) for i in range(n) if mask & (1 << i))
        ok = all(chosen[i][0] >= chosen[i - 1][1] for i in range(1, len(chosen)))
        if ok:
            best = max(best, len(chosen))
    return best

