public int maxActivities(int[] start, int[] finish) {
    int n = start.length;
    Integer[] idx = new Integer[n];
    for (int i = 0; i < n; i++) idx[i] = i;
    Arrays.sort(idx, (a, b) -> Integer.compare(finish[a], finish[b]));
    int count = 0;
    long lastEnd = Long.MIN_VALUE;
    for (int i = 0; i < n; i++) {
        int j = idx[i];
        if (start[j] >= lastEnd) {
            count++;
            lastEnd = finish[j];
        }
    }
    return count;
}

