def max_activities(self, start: list[int], finish: list[int]) -> int:
    activities = sorted(zip(start, finish), key=lambda a: a[1])
    count = 0
    last_end = float('-inf')
    for s, f in activities:
        if s >= last_end:
            count += 1
            last_end = f
    return count

